    for (int i = 0; i <= item.len; i++) begin
      int wait_count = 0;
      // Wait for R beat
      do begin
        @(posedge vif.ACLK);
        wait_count++;
        if (wait_count == 5 || wait_count == 20 || (wait_count > 0 && wait_count % 100 == 0)) begin
          `uvm_info("DRV", $sformatf("WAITING beat=%0d wait_count=%0d | DUT: rd_state=%0d RVALID=%0b RREADY=%0b RDATA=%0h rd_addr=%0h rd_beat=%0d rd_error=%0b",
