                    tb_top.u_dut.rd_state,
                    vif.RVALID,
                    vif.RREADY,
                    vif.RDATA,
                    tb_top.u_dut.rd_addr,
                    tb_top.u_dut.rd_beat,
                    tb_top.u_dut.rd_error), UVM_LOW)
        end
        if (wait_count > 1000) begin
          `uvm_fatal("DRV", $sformatf("Stuck waiting for RVALID at beat %0d - giving up", i))
        end
      end while (vif.RVALID !== 1'b1);

      item.data[i] = vif.RDATA;
      item.resp[i] = vif.RRESP;

      if ((i % 32) == 0) begin
        `uvm_info("DRV", $sformatf("drive_read: progress beat %0d/%0d RDATA=%0h at %0t",
                  i, item.len, vif.RDATA, $time), UVM_LOW)
      end

      if (i == item.len && vif.RLAST !== 1'b1) begin
        `uvm_error("DRV", "RLAST not asserted on final read beat!")
      end
    end
    vif.RREADY <= 1'b0;
    `uvm_info("DRV", $sformatf("drive_read: COMPLETE at %0t", $time), UVM_LOW)
  endtask

