class axi_monitor extends uvm_monitor;
  `uvm_component_utils(axi_monitor)

  virtual axi_if #(32, 32, 4) vif;
  uvm_analysis_port #(axi_seq_item#(32, 32, 4)) ap;

  function new(string name = "axi_monitor", uvm_component parent = null);
    super.new(name, parent);
    ap = new("ap", this);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual axi_if#(32, 32, 4))::get(this, "", "vif", vif))
      `uvm_fatal("MON", "Could not get vif")
  endfunction

  virtual task run_phase(uvm_phase phase);
    wait(vif.ARESETn == 1'b1);
    `uvm_info("MON", $sformatf("ARESETn deasserted at %0t, monitor starting", $time), UVM_LOW)
    fork
      monitor_writes();
      monitor_reads();
    join_none
  endtask

  // ──────────────────────────────────────────────────────────
  // Observes AW -> W -> B sequentially (matches DUT 1-outstanding limit)
  // ──────────────────────────────────────────────────────────
  task monitor_writes();
    axi_seq_item#(32, 32, 4) w_item;
    forever begin
      // Wait for AW handshake
      @(posedge vif.ACLK iff (vif.AWVALID === 1'b1 && vif.AWREADY === 1'b1));

      w_item = axi_seq_item#(32, 32, 4)::type_id::create("w_item");
      w_item.dir   = AXI_WRITE;
      w_item.id    = vif.AWID;
      w_item.addr  = vif.AWADDR;
      w_item.len   = vif.AWLEN;
      w_item.size  = vif.AWSIZE;
      w_item.burst = vif.AWBURST;

      `uvm_info("MON", $sformatf("AW captured: id=%0h addr=%0h len=%0d at %0t",
                w_item.id, w_item.addr, w_item.len, $time), UVM_HIGH)

      w_item.data = new[w_item.len + 1];
      w_item.strb = new[w_item.len + 1];

      // Capture each W beat
      for (int i = 0; i <= w_item.len; i++) begin
        @(posedge vif.ACLK iff (vif.WVALID === 1'b1 && vif.WREADY === 1'b1));
        w_item.data[i] = vif.WDATA;
        w_item.strb[i] = vif.WSTRB;

        if (vif.WLAST === 1'b1 && i != w_item.len) begin
          `uvm_warning("MON", $sformatf("WLAST asserted at beat %0d but expected final beat at %0d",
                       i, w_item.len))
        end
      end

      // Wait for B handshake
      @(posedge vif.ACLK iff (vif.BVALID === 1'b1 && vif.BREADY === 1'b1));
      w_item.resp = new[1];
      w_item.resp[0] = vif.BRESP;

      `uvm_info("MON", $sformatf("Write txn complete: id=%0h BRESP=%0b at %0t",
                w_item.id, w_item.resp[0], $time), UVM_HIGH)

      ap.write(w_item);
    end
  endtask

  // ──────────────────────────────────────────────────────────
  // Observes AR -> R
  // ──────────────────────────────────────────────────────────
  task monitor_reads();
    axi_seq_item#(32, 32, 4) r_item;
    forever begin
      // Wait for AR handshake
      @(posedge vif.ACLK iff (vif.ARVALID === 1'b1 && vif.ARREADY === 1'b1));

      r_item = axi_seq_item#(32, 32, 4)::type_id::create("r_item");
      r_item.dir   = AXI_READ;
      r_item.id    = vif.ARID;
      r_item.addr  = vif.ARADDR;
      r_item.len   = vif.ARLEN;
      r_item.size  = vif.ARSIZE;
      r_item.burst = vif.ARBURST;

      `uvm_info("MON", $sformatf("AR captured: id=%0h addr=%0h len=%0d at %0t",
                r_item.id, r_item.addr, r_item.len, $time), UVM_HIGH)

      r_item.data = new[r_item.len + 1];
      r_item.resp = new[r_item.len + 1];

      // Capture each R beat
      for (int i = 0; i <= r_item.len; i++) begin
        @(posedge vif.ACLK iff (vif.RVALID === 1'b1 && vif.RREADY === 1'b1));
        r_item.data[i] = vif.RDATA;
        r_item.resp[i] = vif.RRESP;

        if (i == r_item.len && vif.RLAST !== 1'b1) begin
          `uvm_warning("MON", "RLAST not asserted on final read beat")
        end
        if (i != r_item.len && vif.RLAST === 1'b1) begin
          `uvm_warning("MON", $sformatf("RLAST asserted early at beat %0d (expected at %0d)",
                       i, r_item.len))
        end
      end

      `uvm_info("MON", $sformatf("Read txn complete: id=%0h at %0t",
                r_item.id, $time), UVM_HIGH)

      ap.write(r_item);
    end
  endtask

endclass

