// Scoreboard (uvm_scoreboard)
// ════════════════════════════════════════════════════════════

class axi_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(axi_scoreboard)

  uvm_analysis_imp #(axi_seq_item#(32, 32, 4), axi_scoreboard) ap_imp;

  logic [7:0] mem [longint];

  localparam logic [1:0] RESP_OKAY   = 2'b00;
  localparam logic [1:0] RESP_SLVERR = 2'b10;
  localparam logic [1:0] BURST_RSVD  = 2'b11;
  localparam logic [1:0] BURST_WRAP  = 2'b10;
  localparam int         MEM_DEPTH   = 256;
  localparam logic [31:0] MEM_BYTES  = MEM_DEPTH * 4;  // 1024 bytes

  function new(string name = "axi_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    ap_imp = new("ap_imp", this);
  endfunction

  function logic size_ok(logic [2:0] axsize);
    return (axsize <= 2);
  endfunction

  function logic burst_ok(logic [1:0] axburst);
    return (axburst != BURST_RSVD);
  endfunction

  function logic wrap_len_ok(logic [7:0] axlen);
    int unsigned beats = axlen + 1;
    return (beats == 2) || (beats == 4) || (beats == 8) || (beats == 16);
  endfunction

  function logic addr_aligned_to_size(logic [31:0] addr, logic [2:0] axsize);
    logic [31:0] mask = (1 << axsize) - 1;
    return ((addr & mask) == 0);
  endfunction

  function logic wrap_burst_legal(logic [31:0] addr, logic [2:0] axsize, logic [7:0] axlen, logic [1:0] axburst);
    if (axburst != BURST_WRAP) return 1'b1;
    return size_ok(axsize) && addr_aligned_to_size(addr, axsize) && wrap_len_ok(axlen);
  endfunction

  function logic req_ok(logic [31:0] addr, logic [2:0] axsize, logic [7:0] axlen, logic [1:0] axburst);
    return size_ok(axsize) && burst_ok(axburst) && wrap_burst_legal(addr, axsize, axlen, axburst);
  endfunction

  function logic addr_in_bounds(logic [31:0] addr);
    return (addr < MEM_BYTES);
  endfunction

  function logic [31:0] next_addr_axi(logic [31:0] cur, logic [31:0] start, logic [2:0] sz, logic [1:0] brst, logic [7:0] ln, logic [7:0] beat);
    logic [31:0] sz_bytes = (1 << sz);
    logic [31:0] sz_mask = sz_bytes - 1;
    logic [31:0] aligned = start & ~sz_mask;
    logic [31:0] container = sz_bytes * (ln + 1);
    logic [31:0] wrap_bdry = start - (start % container);
    logic [31:0] up_wrap = wrap_bdry + container;
    logic [31:0] nxt;

    if (brst == 2'b00) nxt = cur;
    else begin
      if ((beat == 0) && ((start & sz_mask) != 0)) nxt = aligned + sz_bytes;
      else nxt = cur + sz_bytes;
      if (brst == BURST_WRAP && nxt >= up_wrap) nxt = wrap_bdry;
    end
    return nxt;
  endfunction

  virtual function void write(axi_seq_item#(32, 32, 4) item);
    logic req_err  = ~req_ok(item.addr, item.size, item.len, item.burst);
    logic [31:0] cur_addr = item.addr;

    if (item.dir == AXI_WRITE) begin
      logic walks_oob = 1'b0;
      logic [31:0] check_addr = item.addr;
      
      // Predict if the burst ever goes out of bounds for the BRESP check
      for (int i = 0; i <= item.len; i++) begin
        if (!addr_in_bounds(check_addr)) begin
          walks_oob = 1'b1;
          break;
        end
        check_addr = next_addr_axi(check_addr, item.addr, item.size, item.burst, item.len, i);
      end

      if (req_err || walks_oob) begin
        if (item.resp[0] !== RESP_SLVERR)
          `uvm_error("SCB_WR_RESP", $sformatf("Expected SLVERR (req_err=%0b walks_oob=%0b), got %0b",
                     req_err, walks_oob, item.resp[0]))
      end else begin
        if (item.resp[0] !== RESP_OKAY)
          `uvm_error("SCB_WR_RESP", $sformatf("Expected OKAY, got %0b", item.resp[0]))
      end

      // Update mem: match DUT behavior by writing valid beats until an error is hit
      if (!req_err) begin
        logic beat_err = 1'b0;
        for (int i = 0; i <= item.len; i++) begin
          if (!addr_in_bounds(cur_addr)) begin
            beat_err = 1'b1; // Stop writing once we cross the boundary
          end
          
          if (!beat_err) begin
            for (int lane = 0; lane < 4; lane++) begin
              if (item.strb[i][lane]) begin
                mem[(cur_addr & ~32'h3) + lane] = item.data[i][8*lane +: 8];
              end
            end
          end
          cur_addr = next_addr_axi(cur_addr, item.addr, item.size, item.burst, item.len, i);
        end
      end
    end else begin
      // Read verification
      logic exp_err = req_err;

      for (int i = 0; i <= item.len; i++) begin
        logic [1:0] exp_resp = exp_err ? RESP_SLVERR : RESP_OKAY;
        if (item.resp[i] !== exp_resp)
          `uvm_error("SCB_RD_RESP", $sformatf("Beat %0d: Expected resp %0b, got %0b", i, exp_resp, item.resp[i]))

        if (!exp_err) begin
          logic [31:0] expected_data = '0;
          
          if (addr_in_bounds(cur_addr)) begin
            int size_bytes = 1 << item.size;
            int lower_lane = cur_addr % 4;
            int upper_lane;
            
            // Calculate upper lane based on alignment
            if ((cur_addr & (size_bytes - 1)) == 0) begin
              upper_lane = lower_lane + size_bytes - 1;
            end else begin
              upper_lane = ((cur_addr & ~(size_bytes - 1)) + size_bytes - 1) % 4;
            end

            // Only fetch expected data for the active lanes
            for (int lane = lower_lane; lane <= upper_lane; lane++) begin
              longint byte_addr = (cur_addr & ~32'h3) + lane;
              if (mem.exists(byte_addr)) begin
                expected_data[8*lane +: 8] = mem[byte_addr];
              end
            end
          end

          if (item.data[i] !== expected_data)
            `uvm_error("SCB_RD_DATA", $sformatf("Addr %0h Beat %0d mismatch. Exp: %0h, Act: %0h",
                                       cur_addr, i, expected_data, item.data[i]))
        end
        cur_addr = next_addr_axi(cur_addr, item.addr, item.size, item.burst, item.len, i);
      end
    end
  endfunction
endclass
// ════════════════════════════════════════════════════════════
// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

class axi_coverage extends uvm_subscriber #(axi_seq_item#(32, 32, 4));
  `uvm_component_utils(axi_coverage)

  axi_seq_item#(32, 32, 4) cov_item;

  covergroup cg_axi_tx;
    option.per_instance = 1;
    
    cp_dir: coverpoint cov_item.dir {
      bins read  = {AXI_READ};
      bins write = {AXI_WRITE};
    }
    
    cp_burst: coverpoint cov_item.burst {
      bins fixed = {2'b00};
      bins incr  = {2'b01};
      bins wrap  = {2'b10};
      bins rsvd  = {2'b11}; // Expected error case
    }
    
    cp_size: coverpoint cov_item.size {
      bins size_1 = {0};
      bins size_2 = {1};
      bins size_4 = {2};
    }
    
    cp_len: coverpoint cov_item.len {
      bins len_1     = {0};
      bins len_short = {[1:15]};
      bins len_long  = {[16:255]};
    }
    
    cp_resp: coverpoint cov_item.resp[0] {
      bins okay   = {2'b00};
      bins slverr = {2'b10};
    }
    
    cr_dir_burst: cross cp_dir, cp_burst;
    cr_dir_resp:  cross cp_dir, cp_resp;
  endgroup

  function new(string name = "axi_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_axi_tx = new();
  endfunction

  virtual function void write(axi_seq_item#(32, 32, 4) t);
    cov_item = t;
    cg_axi_tx.sample();
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Agent (uvm_agent)
// ════════════════════════════════════════════════════════════

class axi_agent extends uvm_agent;
  `uvm_component_utils(axi_agent)

  axi_sequencer sqr;
  axi_driver    drv;
  axi_monitor   mon;

  function new(string name = "axi_agent", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (get_is_active() == UVM_ACTIVE) begin
      sqr = axi_sequencer::type_id::create("sqr", this);
      drv = axi_driver::type_id::create("drv", this);
    end
    mon = axi_monitor::type_id::create("mon", this);
  endfunction

  virtual function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    if (get_is_active() == UVM_ACTIVE) begin
      drv.seq_item_port.connect(sqr.seq_item_export);
    end
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Environment (uvm_env)
// ════════════════════════════════════════════════════════════

class axi_env extends uvm_env;
  `uvm_component_utils(axi_env)

  axi_agent      agent;
  axi_scoreboard scb;
  axi_coverage   cov;

  function new(string name = "axi_env", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    agent = axi_agent::type_id::create("agent", this);
    scb   = axi_scoreboard::type_id::create("scb", this);
    cov   = axi_coverage::type_id::create("cov", this);
  endfunction

  virtual function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    agent.mon.ap.connect(scb.ap_imp);
    agent.mon.ap.connect(cov.analysis_export);
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Test (uvm_test)
// ════════════════════════════════════════════════════════════

class axi_test extends uvm_test;
  `uvm_component_utils(axi_test)

  axi_env env;

  function new(string name = "axi_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = axi_env::type_id::create("env", this);
  endfunction

  virtual task run_phase(uvm_phase phase);
    axi_reset_sequence  reset_seq  = axi_reset_sequence::type_id::create("reset_seq");
    axi_rand_sequence   rand_seq   = axi_rand_sequence::type_id::create("rand_seq");
    axi_corner_sequence corner_seq = axi_corner_sequence::type_id::create("corner_seq");

    phase.raise_objection(this);
    
    `uvm_info("TEST", "About to start reset_seq", UVM_LOW)
    reset_seq.start(env.agent.sqr);
    `uvm_info("TEST", "reset_seq DONE", UVM_LOW)
    
    if (!rand_seq.randomize()) `uvm_fatal("TEST", "rand_seq randomize failed")
    `uvm_info("TEST", $sformatf("rand_seq randomized: num_tx=%0d", rand_seq.num_tx), UVM_LOW)
    rand_seq.start(env.agent.sqr);
    `uvm_info("TEST", "rand_seq DONE", UVM_LOW)
    
    corner_seq.start(env.agent.sqr);
    `uvm_info("TEST", "corner_seq DONE", UVM_LOW)
    
    phase.drop_objection(this);
endtask
endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

module tb_top;
  `include "uvm_macros.svh"
  import uvm_pkg::*;

  logic ACLK;
  logic ARESETn;

  // Interface Instance
  axi_if #(
    .ADDR_WIDTH(32),
    .DATA_WIDTH(32),
    .ID_WIDTH(4)
  ) axi_vif (.ACLK(ACLK));

  // Drive reset from interface to DUT
  assign axi_vif.ARESETn = ARESETn;

  // DUT Instance
  axi_mem #(
    .ADDR_WIDTH(32),
    .DATA_WIDTH(32),
    .ID_WIDTH(4),
    .MEM_DEPTH(256)
  ) u_dut (
    .ACLK    (ACLK),
    .ARESETn (ARESETn),

    .AWID    (axi_vif.AWID),
    .AWADDR  (axi_vif.AWADDR),
    .AWLEN   (axi_vif.AWLEN),
    .AWSIZE  (axi_vif.AWSIZE),
    .AWBURST (axi_vif.AWBURST),
    .AWVALID (axi_vif.AWVALID),
    .AWREADY (axi_vif.AWREADY),

    .WDATA   (axi_vif.WDATA),
    .WSTRB   (axi_vif.WSTRB),
    .WLAST   (axi_vif.WLAST),
    .WVALID  (axi_vif.WVALID),
    .WREADY  (axi_vif.WREADY),

    .BID     (axi_vif.BID),
    .BRESP   (axi_vif.BRESP),
    .BVALID  (axi_vif.BVALID),
    .BREADY  (axi_vif.BREADY),

    .ARID    (axi_vif.ARID),
    .ARADDR  (axi_vif.ARADDR),
    .ARLEN   (axi_vif.ARLEN),
    .ARSIZE  (axi_vif.ARSIZE),
    .ARBURST (axi_vif.ARBURST),
    .ARVALID (axi_vif.ARVALID),
    .ARREADY (axi_vif.ARREADY),

    .RID     (axi_vif.RID),
    .RDATA   (axi_vif.RDATA),
    .RRESP   (axi_vif.RRESP),
    .RLAST   (axi_vif.RLAST),
    .RVALID  (axi_vif.RVALID),
    .RREADY  (axi_vif.RREADY)
  );

  // Clock Generation
  initial begin
    ACLK = 0;
    forever #5 ACLK = ~ACLK;
  end

  // Reset Generation
  initial begin
    ARESETn = 0;
    #30 ARESETn = 1;
  end

initial begin
     #1ms;
     `uvm_fatal("TB_TOP", "Simulation timeout")
   end

  // UVM Top
  initial begin
    uvm_config_db#(virtual axi_if#(32, 32, 4))::set(null, "*", "vif", axi_vif);
    run_test("axi_test");
  end
endmodule

